def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    recent_opp_defects = 0
    start = max(0, n - 10)
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_opp_defects += 1
    total_opp_defects = 0
    for _, o in history:
        if o == 'D':
            total_opp_defects += 1
    last_my, last_opp = history[-1]
    if n >= 97:
        return 'D'
    if last_opp == 'D':
        return 'D'
    if recent_opp_defects == 0:
        if total_opp_defects == 0:
            if n < 20:
                if n % 10 == 0:
                    return 'D'
            elif n < 50:
                if n % 5 == 0:
                    return 'D'
            else:
                if n % 4 == 0:
                    return 'D'
        else:
            if n % 10 == 0:
                return 'D'
        return 'C'
    else:
        return 'C'
